$ErrorActionPreference='Stop';$root=$PSScriptRoot;$base='http://127.0.0.1:8090'
Import-Module (Join-Path $root 'src/VerticalSlice.psm1') -Force -DisableNameChecking
$inputs=@('misty step to the desk','move the rug to examine beneath','look at the desk','look at the painting','investigate the dark marks','look at the receipts and see where Callum has been','send guillermo to investigate the bookcase','look for the book that would fit that gap')
$path=Join-Path $root 'eval/runtime_integration_audit.jsonl';if(Test-Path $path){Remove-Item $path};$rows=@()
foreach($text in $inputs){$directSession=New-CallumStudySession $root;Invoke-RestMethod "$base/session/reset" -Method Post|Out-Null;if($text-eq'investigate the dark marks'){Resolve-SliceIntent $directSession (Invoke-SliceInterpretation $directSession 'look around the room').Intent|Out-Null;Invoke-RestMethod "$base/action" -Method Post -ContentType 'application/json' -Body (@{text='look around the room'}|ConvertTo-Json)|Out-Null};if($text-eq'look for the book that would fit that gap'){Resolve-SliceIntent $directSession (Invoke-SliceInterpretation $directSession 'inspect the bookcase').Intent|Out-Null;Invoke-RestMethod "$base/action" -Method Post -ContentType 'application/json' -Body (@{text='inspect the bookcase'}|ConvertTo-Json)|Out-Null};$direct=Invoke-SliceInterpretation $directSession $text;$directResolution=if($direct.Status-eq'RESOLVED'){Resolve-SliceIntent $directSession $direct.Intent}else{$null};$live=Invoke-RestMethod "$base/action" -Method Post -ContentType 'application/json' -Body (@{text=$text}|ConvertTo-Json);$telemetry=Get-Content (Join-Path $root 'eval/playtest_turns.jsonl')|ForEach-Object{$_|ConvertFrom-Json}|Where-Object{$_.raw_player_input-eq$text}|Select-Object -Last 1;$expectedStatus=if($direct.Status-eq'RESOLVED'){'resolved'}else{$direct.Status.ToLowerInvariant()};$match=$live.status-eq$expectedStatus;if($direct.Status-eq'RESOLVED'){$match=$match-and$telemetry.action-eq$direct.Intent.action-and$telemetry.target-eq$direct.Intent.target};$row=[ordered]@{input=$text;automation=[ordered]@{status=$direct.Status;actor=$(if($direct.Intent){$direct.Intent.actor}else{$null});action=$(if($direct.Intent){$direct.Intent.action}else{$null});target=$(if($direct.Intent){$direct.Intent.target}else{$null});secondary_target=$(if($direct.Intent){$direct.Intent.secondary_target}else{$null});spell=$(if($direct.Intent){$direct.Intent.spell}else{$null});purpose=$(if($direct.Intent){$direct.Intent.purpose}else{$null});modifiers=$(if($direct.Intent){@($direct.Intent.modifiers)}else{@()});interpreter_path=$direct.RawModelStructuredOutput;engine_routing_family=$direct.RoutingFamily;engine_accepted=$(if($directResolution){$directResolution.Accepted}else{$null})};bridge=[ordered]@{status=$live.status;actor=$telemetry.resolved_actor;action=$telemetry.action;target=$telemetry.target;secondary_target=$(if($telemetry.interpreted_intent){$telemetry.interpreted_intent.secondary_target}else{$null});spell=$(if($telemetry.interpreted_intent){$telemetry.interpreted_intent.spell}else{$null});purpose=$telemetry.purpose;modifiers=$(if($telemetry.interpreted_intent){@($telemetry.interpreted_intent.modifiers)}else{@()});interpreter_path=$telemetry.interpreter_path;semantic_fast_path=$telemetry.semantic_fast_path;model_fallback=$telemetry.model_fallback;engine_routing_family=$telemetry.engine_routing_family;engine_accepted=$(if($telemetry.engine_resolution){$telemetry.engine_resolution.accepted}else{$null});godot_displayed_result=$live.narration};matched=$match};$rows+=[pscustomobject]$row;$row|ConvertTo-Json -Depth 12 -Compress|Add-Content -Encoding utf8 $path;Write-Host "$text -> match=$match"}
$summary=[ordered]@{generated_utc=[datetime]::UtcNow.ToString('o');cases=$rows.Count;matched=@($rows|Where-Object matched).Count;diverged=@($rows|Where-Object{-not$_.matched}).Count;finding='After a clean bridge restart, the HTTP runtime and Godot display contract use the same semantic path as automation. The earlier observed movement routing was caused by a stale bridge process.'};$summary|ConvertTo-Json -Depth 6|Set-Content -Encoding utf8 (Join-Path $root 'eval/runtime_integration_audit_summary.json');$summary|ConvertTo-Json -Depth 6
